                {
                  allLostReports.filter(
                    (r) =>
                      r.report_type === "LOST" && r.report_status === "ACCEPTED"
                  ).length
                }
                )
              </div>
              <div className="reports-grid">
                {loading ? (
                  <div className="loading">
                    Loading approved lost pet reports...
                  </div>
                ) : allLostReports.filter(
                    (r) =>
                      r.report_type === "LOST" && r.report_status === "ACCEPTED"
                  ).length > 0 ? (
                  allLostReports
                    .filter(
                      (r) =>
                        r.report_type === "LOST" &&
