                        <div className="pet-medical-info">
                          {pet.is_vaccinated && (
                            <span className="badge vaccinated">
                              ✓ Vaccinated
                            </span>
                          )}
                          {pet.is_diseased && (
                            <span className="badge health-issue">
                              ⚠ Health Condition
                            </span>
                          )}
                        </div>
                        <div className="pet-status-badge available-adoption">
