                    <div className="form-group">
                      <label>Breed</label>
                      <input
                        type="text"
                        value={postAdoptionForm.breed}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            breed: e.target.value,
                          })
