                      }
                    />
                  </div>

                  <div className="form-group checkbox-group">
                    <label>
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_vaccinated}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_vaccinated: e.target.checked,
                          })
                        }
                      />
