                            value={postAdoptionForm.vaccination_date}
                            onChange={(e) =>
                              setPostAdoptionForm({
                                ...postAdoptionForm,
                                vaccination_date: e.target.value,
                              })
                            }
                          />
                        </div>
                        <div className="form-group">
                          <label>Vaccination Type</label>
                          <input
                            type="text"
                            value={postAdoptionForm.vaccination_type}
                            onChange={(e) =>
                              setPostAdoptionForm({
                                ...postAdoptionForm,
                                vaccination_type: e.target.value,
