                  <div className="form-group checkbox-group">
                    <label>
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_diseased}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_diseased: e.target.checked,
                          })
